/* The Skate Lab's book (AOG-SKATE-BOOK-V1, 2026-10-12): every trick's words and the Questions room's answers.
   Jimmy: "this has to be silent when not being used … lightning fast". aog-skate.js asks for this file only when the
   Trick book or Questions opens, so a visit to Build a board or the physics rooms never downloads it. */
window.AOG_SKATE_BOOK = {
TRICKS: [
  { id: "stance", lv: 1, room: "balance", feet: { f: [0.13, 0, 10], b: [-0.17, 0, 5] },
    en: { n: "Stance: regular or goofy", steps: ["Stand on the board on grass or carpet, so it cannot roll.", "Try your left foot in front, then your right. The one that feels steady is your stance: left in front is regular, right in front is goofy. Both are fine.", "Put both feet over the bolts, across the board, shoulder-width apart.", "Bend your knees a little, like a spring. Keep your arms loose and out to the sides.", "Look up, where you would go, not at your feet."], fixes: [["The board wobbles", "Bend your knees more and keep your feet over the bolts."], ["I can't tell which foot goes first", "Have a friend give you a gentle push from behind: the foot you step forward with often goes in front."]], sci: "Your feet over the bolts sit right above the wheels, so your weight is inside the base of support." },
    es: { n: "Postura: regular o goofy", steps: ["Párate en la tabla sobre pasto o alfombra, para que no ruede.", "Prueba el pie izquierdo adelante y luego el derecho. El que se sienta firme es tu postura: izquierdo adelante es regular, derecho adelante es goofy. Las dos están bien.", "Pon los dos pies sobre los tornillos, de lado, al ancho de los hombros.", "Dobla un poco las rodillas, como un resorte. Brazos sueltos y hacia los lados.", "Mira hacia arriba, adonde irías, no a tus pies."], fixes: [["La tabla se mueve", "Dobla más las rodillas y deja los pies sobre los tornillos."], ["No sé qué pie va adelante", "Pide a alguien que te empuje suave por detrás: el pie que das adelante suele ser el de adelante."]], sci: "Tus pies sobre los tornillos quedan encima de las ruedas, así tu peso está dentro de la base de apoyo." } },
  { id: "push", lv: 1, room: "ramp", feet: { f: [0.15, 0, -55], b: [0.05, 0.25, 0] }, arrows: [{ from: [0.05, 0.25], to: [-0.35, 0.25] }],
    en: { n: "Pushing", steps: ["Helmet on. Find a smooth, flat place with no cars.", "Put your front foot over the front bolts, pointing toward the nose.", "Push the ground with your back foot, beside the board, behind you.", "Put the back foot on the board over the back bolts, across the board, and turn the front foot sideways.", "Roll. Push again when you slow down. Small pushes are fine."], fixes: [["The board rolls away from my front foot", "Keep most of your weight on the front foot while you push."], ["I wobble after I push", "Turn your front foot sideways as soon as your back foot is on, and bend your knees."]], sci: "A push is a force. The ground pushes back on your foot (Newton's third law) and that starts you rolling." },
    es: { n: "Empujar", steps: ["Ponte el casco. Busca un lugar liso y plano, sin autos.", "Pon el pie de adelante sobre los tornillos delanteros, apuntando a la nariz.", "Empuja el suelo con el pie de atrás, al lado de la tabla, detrás de ti.", "Sube el pie de atrás sobre los tornillos traseros, de lado, y gira el pie de adelante de lado.", "Rueda. Empuja otra vez cuando vayas más lento. Empujes pequeños están bien."], fixes: [["La tabla se escapa del pie de adelante", "Deja casi todo tu peso en el pie de adelante mientras empujas."], ["Me tambaleo después de empujar", "Gira el pie de adelante de lado en cuanto subas el de atrás, y dobla las rodillas."]], sci: "Un empujón es una fuerza. El suelo empuja tu pie de vuelta (tercera ley de Newton) y eso te pone a rodar." } },
  { id: "stop", lv: 1, room: "grind", feet: { f: [0.15, 0, -50], b: [0.0, 0.25, 0] }, arrows: [{ from: [-0.05, 0.25], to: [-0.3, 0.25] }],
    en: { n: "Stopping: the foot brake", steps: ["Roll slowly on flat ground.", "Turn your front foot to point toward the nose, with your weight on it.", "Lower your back foot and let the sole touch the ground lightly beside the board.", "Press a little harder to slow down. Keep the foot flat, not on the heel.", "When you are slow enough, step off."], fixes: [["My foot bounces", "Touch down lightly at first, then press slowly."], ["I'm too fast to try", "Practice the stop at walking speed first."]], sci: "Your shoe rubbing the ground makes friction, which turns your motion energy into heat." },
    es: { n: "Frenar con el pie", steps: ["Rueda despacio en suelo plano.", "Gira el pie de adelante hacia la nariz, con tu peso en él.", "Baja el pie de atrás y deja que la suela roce el suelo al lado de la tabla.", "Presiona un poco más para frenar. El pie plano, no sobre el talón.", "Cuando vayas lento, bájate."], fixes: [["Mi pie rebota", "Toca el suelo suave al principio y luego presiona poco a poco."], ["Voy muy rápido para probar", "Practica el frenado primero a paso de caminar."]], sci: "Tu zapato rozando el suelo hace fricción, que convierte tu energía de movimiento en calor." } },
  { id: "kickturn", lv: 2, room: "balance", feet: { f: [0.1, 0, 10], b: [-0.32, 0, 5] }, arrows: [{ from: [0.3, 0], to: [0.3, 0.25], curve: 1 }],
    en: { n: "Kickturn", steps: ["Stand still on a flat, smooth place first, with your back foot on the tail.", "Press the tail gently so the front wheels lift a little.", "Turn your shoulders and head where you want to go; the board follows.", "Put the front wheels down. Start with small turns, then bigger ones.", "Try it while rolling slowly."], fixes: [["The board shoots out", "Press the tail more gently and keep weight on the front foot too."], ["It won't turn", "Turn your shoulders first. The hips and the board follow."]], sci: "The tail is a lever: pressing it turns the board about the back wheels, so the front wheels lift and there is less friction to stop the turn." },
    es: { n: "Kickturn", steps: ["Primero quieto en un lugar plano y liso, con el pie de atrás en la cola.", "Presiona la cola suave para que suban un poco las ruedas de adelante.", "Gira los hombros y la cabeza adonde quieres ir; la tabla te sigue.", "Baja las ruedas de adelante. Empieza con giros pequeños, luego más grandes.", "Pruébalo rodando despacio."], fixes: [["La tabla se escapa", "Presiona la cola más suave y deja peso también en el pie de adelante."], ["No gira", "Gira primero los hombros. La cadera y la tabla siguen."]], sci: "La cola es una palanca: al presionarla, la tabla gira sobre las ruedas de atrás, suben las de adelante y hay menos fricción que frene el giro." } },
  { id: "tictac", lv: 2, room: "balance", feet: { f: [0.1, 0, 10], b: [-0.32, 0, 5] },
    en: { n: "Tic-tac", steps: ["Start with small kickturns: lift the front wheels and turn a little to the toe side.", "Put them down and turn a little to the heel side.", "Keep going side to side in a steady rhythm.", "Each small turn moves you forward without pushing.", "Keep your knees bent and your shoulders leading."], fixes: [["I go nowhere", "Make the turns a little wider and quicker."], ["I lose balance", "Lift the front wheels only a little."]], sci: "Swinging the board side to side turns small twists into forward motion, like a swimmer's kick." },
    es: { n: "Tic-tac", steps: ["Empieza con kickturns pequeños: sube las ruedas de adelante y gira un poco hacia el lado de los dedos.", "Bájalas y gira un poco hacia el lado de los talones.", "Sigue de lado a lado con un ritmo parejo.", "Cada giro pequeño te mueve adelante sin empujar.", "Rodillas dobladas y los hombros guían."], fixes: [["No avanzo", "Haz giros un poco más anchos y rápidos."], ["Pierdo el equilibrio", "Sube solo un poco las ruedas de adelante."]], sci: "Mover la tabla de lado a lado convierte pequeños giros en avance, como la patada de un nadador." } },
  { id: "manual", lv: 2, room: "balance", feet: { f: [0.08, 0, 10], b: [-0.27, 0, 5] },
    en: { n: "Manual", steps: ["Roll slowly on flat ground.", "Shift your weight back until your center of mass is right over the back wheels.", "The front wheels lift. Keep the tail just off the ground.", "Use tiny moves of your arms and hips to stay balanced.", "Put the front wheels down before you lose it. Try for a short distance first."], fixes: [["The tail scrapes", "Your weight is too far back. Move it forward a little."], ["The front won't lift", "Lean back more, and keep your back foot near the tail."]], sci: "A manual is balance on one axle: the line of your weight falls right over the back wheels, so it cannot turn the board either way." },
    es: { n: "Manual", steps: ["Rueda despacio en suelo plano.", "Lleva tu peso atrás hasta que tu centro de masa quede justo sobre las ruedas de atrás.", "Suben las ruedas de adelante. La cola queda justo sobre el suelo.", "Usa pequeños movimientos de brazos y cadera para mantenerte.", "Baja las ruedas antes de perderlo. Prueba primero una distancia corta."], fixes: [["La cola raspa", "Tu peso está muy atrás. Muévelo un poco adelante."], ["La nariz no sube", "Inclínate más atrás y deja el pie de atrás cerca de la cola."]], sci: "Un manual es equilibrio sobre un eje: la línea de tu peso cae justo sobre las ruedas de atrás, así no gira la tabla para ningún lado." } },
  { id: "dropin", lv: 2, room: "ramp", feet: { f: [0.15, 0, 5], b: [-0.33, 0, 5] },
    en: { n: "Dropping in", steps: ["Start on a small ramp, with a coach or a grown-up beside you, in full pads and a helmet.", "Put the tail on the coping (the metal edge), with the back wheels hanging over the ramp. Hold it with your back foot.", "Put your front foot over the front bolts.", "Lean forward, onto your front foot, and push the front wheels down onto the ramp. Commit all the way.", "Keep your knees bent and your weight forward as you roll down."], fixes: [["The board shoots out in front", "You leaned back. Leaning forward feels scary but keeps the board under you."], ["I freeze at the top", "That is normal. Practice on a smaller ramp, or have someone hold your hand."]], sci: "On a slope, gravity pulls you along the ramp. If your weight stays behind the wheels, the board speeds away under you. Leaning forward keeps your center of mass over your feet." },
    es: { n: "Dropping in (entrar a la rampa)", steps: ["Empieza en una rampa pequeña, con un entrenador o un adulto al lado, con protecciones y casco.", "Pon la cola sobre el coping (el borde de metal), con las ruedas de atrás colgando sobre la rampa. Sujétala con el pie de atrás.", "Pon el pie de adelante sobre los tornillos delanteros.", "Inclínate adelante, sobre el pie de adelante, y baja las ruedas delanteras a la rampa. Decídete del todo.", "Rodillas dobladas y el peso adelante mientras bajas."], fixes: [["La tabla se me escapa adelante", "Te inclinaste atrás. Inclinarse adelante da miedo pero mantiene la tabla bajo ti."], ["Me quedo congelado arriba", "Es normal. Practica en una rampa más pequeña o pide que te den la mano."]], sci: "En una pendiente, la gravedad te jala por la rampa. Si tu peso queda detrás de las ruedas, la tabla acelera bajo ti. Inclinarte adelante mantiene tu centro de masa sobre tus pies." } },
  { id: "ollie", lv: 3, room: "ollie", feet: { f: [0.05, 0, 15], b: [-0.33, 0.03, 0] }, arrows: [{ from: [0.05, 0], to: [0.3, -0.01] }, { from: [-0.37, 0.03], to: [-0.37, 0.03], down: 1 }],
    en: { n: "Ollie", steps: ["Practice standing still on grass or carpet first.", "Back foot: the ball of the foot on the tail. Front foot: just behind the front bolts.", "Crouch: bend your knees low.", "Snap the tail down hard with your back foot, and jump.", "Right after the snap, slide your front foot up toward the nose. The side of your shoe drags on the grip tape.", "Lift both knees up so the board can rise; push the nose level with your front foot.", "Land with both feet over the bolts and bend your knees."], fixes: [["The board barely leaves the ground", "Snap the tail faster, and slide the front foot after the snap, not before."], ["The board lands on its tail", "Slide the front foot higher and sooner to level the board."], ["I land with my feet off the bolts", "Jump straight up, not forward, and look down at the board."]], sci: "The tail is a lever about the back wheels; the front foot's friction drags the board up and levels it. A 30 cm ollie keeps you in the air about half a second." },
    es: { n: "Ollie", steps: ["Practica primero quieto en pasto o alfombra.", "Pie de atrás: la punta del pie en la cola. Pie de adelante: justo detrás de los tornillos delanteros.", "Agáchate: dobla bien las rodillas.", "Golpea la cola fuerte con el pie de atrás y salta.", "Justo después del golpe, desliza el pie de adelante hacia la nariz. El lado del zapato roza la lija.", "Sube las dos rodillas para que la tabla suba; nivela la nariz con el pie de adelante.", "Aterriza con los dos pies sobre los tornillos y dobla las rodillas."], fixes: [["La tabla casi no sube", "Golpea la cola más rápido y desliza el pie de adelante después del golpe, no antes."], ["La tabla cae de cola", "Desliza el pie de adelante más alto y antes, para nivelar la tabla."], ["Aterrizo con los pies fuera de los tornillos", "Salta hacia arriba, no hacia adelante, y mira la tabla."]], sci: "La cola es una palanca sobre las ruedas de atrás; la fricción del pie de adelante sube y nivela la tabla. Un ollie de 30 cm te deja en el aire medio segundo." } },
  { id: "shove", lv: 3, room: "flip", feet: { f: [0.12, 0, 10], b: [-0.34, 0.05, 0] }, arrows: [{ from: [-0.36, 0.05], to: [-0.3, -0.2], curve: 1 }],
    en: { n: "Pop shove-it", steps: ["Back foot on the tail, toes near the toe-side edge, ready to scoop.", "Front foot over the front bolts, a little toward the heel side.", "Pop the tail and scoop it behind you with your back foot.", "Jump up. Let the board spin half a turn flat under you.", "Catch it with your back foot, then your front foot, over the bolts, and land with bent knees."], fixes: [["The board flies away", "Scoop less hard, and jump straight up."], ["The board only turns a quarter", "Scoop with more snap from the ankle."]], sci: "The scoop pushes the tail sideways, a torque about the up-down axis, so the board spins flat." },
    es: { n: "Pop shove-it", steps: ["Pie de atrás en la cola, con los dedos cerca del borde del lado de los dedos, listo para empujar.", "Pie de adelante sobre los tornillos delanteros, un poco hacia el lado de los talones.", "Golpea la cola y empújala hacia atrás con el pie de atrás.", "Salta. Deja que la tabla gire media vuelta plana bajo ti.", "Atrápala con el pie de atrás, luego con el de adelante, sobre los tornillos, y aterriza con las rodillas dobladas."], fixes: [["La tabla sale volando", "Empuja menos fuerte y salta recto hacia arriba."], ["La tabla gira solo un cuarto", "Empuja con más golpe del tobillo."]], sci: "El empuje mueve la cola de lado, un torque sobre el eje vertical, y la tabla gira plana." } },
  { id: "kickflip", lv: 3, room: "flip", feet: { f: [0.02, -0.02, 35], b: [-0.33, 0.02, 0] }, arrows: [{ from: [0.05, 0], to: [0.33, 0.12] }],
    en: { n: "Kickflip", steps: ["Get a steady ollie first.", "Front foot angled, just behind the front bolts, toes near the toe-side edge. Back foot on the tail.", "Crouch, snap the tail, and slide your front foot up toward the nose, like an ollie.", "At the end of the slide, flick the front foot off the toe-side corner of the nose.", "Lift your knees high. The board flips under you.", "When you see the grip tape again, catch it with your back foot, then your front foot, and land over the bolts."], fixes: [["The board flips but flies forward", "Flick more to the side and less forward."], ["It doesn't flip all the way", "Flick off the very corner of the nose, with snap."], ["I land on the board's edge", "Wait to see the grip tape before you put your feet down."]], sci: "The flick off the corner gives the board a turning push about its long axis. It spins about 720° per second in a half-second of air." },
    es: { n: "Kickflip", steps: ["Primero ten un ollie firme.", "Pie de adelante en ángulo, justo detrás de los tornillos delanteros, con los dedos cerca del borde del lado de los dedos. Pie de atrás en la cola.", "Agáchate, golpea la cola y desliza el pie de adelante hacia la nariz, como un ollie.", "Al final, raspa con el pie de adelante la esquina de la nariz del lado de los dedos.", "Sube bien las rodillas. La tabla gira bajo ti.", "Cuando veas otra vez la lija, atrápala con el pie de atrás, luego el de adelante, y aterriza sobre los tornillos."], fixes: [["La tabla gira pero se va adelante", "Raspa más hacia el lado y menos hacia adelante."], ["No da la vuelta completa", "Raspa justo la esquina de la nariz, con golpe."], ["Caigo sobre el borde", "Espera a ver la lija antes de bajar los pies."]], sci: "Raspar la esquina da a la tabla un empuje de giro sobre su eje largo. Gira unos 720° por segundo en medio segundo de aire." } },
  { id: "heelflip", lv: 3, room: "flip", feet: { f: [0.08, 0.03, 0], b: [-0.33, 0.02, 0] }, arrows: [{ from: [0.1, 0.03], to: [0.33, -0.13] }],
    en: { n: "Heelflip", steps: ["Front foot straight across the board, toes hanging a little over the toe-side edge. Back foot on the tail.", "Crouch and snap the tail like an ollie.", "Slide your front foot up, then kick your heel off the heel-side corner of the nose, forward and out.", "Lift your knees; the board flips the other way from a kickflip.", "Catch it with both feet over the bolts and bend your knees."], fixes: [["The board flies away behind you", "Kick forward more and less to the side."], ["It turns sideways", "Keep your shoulders square to the board."]], sci: "The heel pushes the heel-side edge, a torque about the long axis in the opposite direction to a kickflip." },
    es: { n: "Heelflip", steps: ["Pie de adelante recto, de lado, con los dedos un poco fuera del borde del lado de los dedos. Pie de atrás en la cola.", "Agáchate y golpea la cola como en un ollie.", "Desliza el pie de adelante y luego golpea con el talón la esquina de la nariz del lado de los talones, hacia adelante y afuera.", "Sube las rodillas; la tabla gira al revés que en un kickflip.", "Atrápala con los dos pies sobre los tornillos y dobla las rodillas."], fixes: [["La tabla se va hacia atrás", "Golpea más hacia adelante y menos hacia el lado."], ["Gira de lado", "Mantén los hombros alineados con la tabla."]], sci: "El talón empuja el borde del lado de los talones, un torque sobre el eje largo en dirección contraria al kickflip." } },
  { id: "fs180", lv: 3, room: "flip", feet: { f: [0.1, 0, 10], b: [-0.3, 0, 5] },
    en: { n: "Frontside 180", steps: ["Get a steady ollie first.", "Before you pop, wind your shoulders back, away from where you will turn.", "Pop an ollie and turn your shoulders toward your front side (your chest leads).", "Your hips and the board follow your shoulders, half a turn.", "Land rolling backward (fakie), knees bent, and look where you are going."], fixes: [["I only turn a quarter", "Wind up more before the pop, and lead with your head."], ["I land off the board", "Pop straight up and keep your feet over the bolts."]], sci: "All the spin must start while the wheels touch the ground. In the air, your angular momentum stays the same; pulling your arms in spins you faster." },
    es: { n: "Frontside 180", steps: ["Primero ten un ollie firme.", "Antes del golpe, gira los hombros hacia atrás, al lado contrario del giro.", "Haz un ollie y gira los hombros hacia tu frente (el pecho guía).", "La cadera y la tabla siguen a los hombros, media vuelta.", "Aterriza rodando hacia atrás (fakie), rodillas dobladas, y mira adonde vas."], fixes: [["Solo giro un cuarto", "Gira más los hombros antes del golpe y guía con la cabeza."], ["Caigo fuera de la tabla", "Salta recto y deja los pies sobre los tornillos."]], sci: "Todo el giro debe empezar mientras las ruedas tocan el suelo. En el aire tu momento angular no cambia; juntar los brazos te hace girar más rápido." } },
  { id: "fifty", lv: 4, room: "grind", feet: { f: [0.15, 0, 5], b: [-0.2, 0, 5] },
    en: { n: "50-50 grind", steps: ["Start on a low painted curb or a low flat bar, with a helmet and pads. Wax the edge.", "Roll toward the curb at a slight angle, at a steady, medium speed.", "Ollie up so both trucks land on the edge, front and back, with your feet over the bolts.", "Keep your weight centered over the edge and your knees bent. Look at the end.", "At the end, lift the nose a little and roll off, or ollie off."], fixes: [["I slide off the side", "Come in at a smaller angle and land with your weight centered over the edge."], ["I stop on the curb", "Come in faster, or add wax."]], sci: "Friction slows you at μg the whole way. The distance you can grind is v² / (2μg): double your speed and you go four times as far." },
    es: { n: "Grind 50-50", steps: ["Empieza en un bordillo pintado bajo o una barra plana baja, con casco y protecciones. Pon cera en el borde.", "Rueda hacia el bordillo en un ángulo pequeño, a una rapidez media y pareja.", "Haz un ollie para que los dos ejes caigan en el borde, con los pies sobre los tornillos.", "Peso centrado sobre el borde y rodillas dobladas. Mira el final.", "Al final, sube un poco la nariz y sal rodando, o sal con un ollie."], fixes: [["Me resbalo por el lado", "Entra con menos ángulo y cae con el peso centrado sobre el borde."], ["Me detengo en el bordillo", "Entra más rápido o pon más cera."]], sci: "La fricción te frena a μg todo el camino. La distancia que puedes hacer es v² / (2μg): duplica la rapidez y llegas cuatro veces más lejos." } },
  { id: "fiveo", lv: 4, room: "grind", feet: { f: [0.12, 0, 5], b: [-0.3, 0, 5] },
    en: { n: "5-0 grind", steps: ["Get a steady 50-50 first, on a low curb with wax.", "Ollie onto the curb so only the back truck lands on the edge.", "Keep the nose up by keeping your weight over the back truck, like a manual.", "Look at the end of the curb.", "Push the nose down or ollie off at the end."], fixes: [["The nose drops onto the curb", "Keep more weight over the back truck."], ["The tail scrapes", "Shift forward a little so the tail stays up."]], sci: "A 5-0 is a manual on an edge: your weight's line falls right over the back truck." },
    es: { n: "Grind 5-0", steps: ["Primero ten un 50-50 firme, en un bordillo bajo con cera.", "Haz un ollie al bordillo para que solo el eje de atrás caiga en el borde.", "Mantén la nariz arriba con el peso sobre el eje de atrás, como un manual.", "Mira el final del bordillo.", "Baja la nariz o sal con un ollie al final."], fixes: [["La nariz cae al bordillo", "Deja más peso sobre el eje de atrás."], ["La cola raspa", "Muévete un poco adelante para que la cola quede arriba."]], sci: "Un 5-0 es un manual sobre un borde: la línea de tu peso cae justo sobre el eje de atrás." } },
  { id: "boardslide", lv: 4, room: "grind", feet: { f: [0.15, 0, 5], b: [-0.2, 0, 5] },
    en: { n: "Boardslide", steps: ["Start on a low flat bar or a waxed curb, with a helmet and pads.", "Roll alongside the bar, close and nearly parallel to it.", "Ollie and turn the board a quarter turn so the middle of the deck lands across the bar.", "Keep your weight centered over the bar and your knees bent.", "At the end, turn the board back a quarter turn and land rolling."], fixes: [["I fall off the far side", "Keep your weight centered and don't lean over the bar."], ["I stop on the bar", "Come in faster or wax the bar."]], sci: "The wood or plastic under the deck slides on metal with less friction than you might think; wax lowers it more." },
    es: { n: "Boardslide", steps: ["Empieza en una barra plana baja o un bordillo con cera, con casco y protecciones.", "Rueda al lado de la barra, cerca y casi paralelo.", "Haz un ollie y gira la tabla un cuarto de vuelta para que el centro de la tabla caiga atravesado sobre la barra.", "Peso centrado sobre la barra y rodillas dobladas.", "Al final, gira la tabla de vuelta un cuarto y aterriza rodando."], fixes: [["Me caigo del otro lado", "Mantén el peso centrado y no te inclines sobre la barra."], ["Me detengo en la barra", "Entra más rápido o pon cera en la barra."]], sci: "La madera o el plástico bajo la tabla resbala en el metal con poca fricción; la cera la baja más." } },
  { id: "rockfakie", lv: 4, room: "ramp", feet: { f: [0.12, 0, 5], b: [-0.3, 0, 5] },
    en: { n: "Rock to fakie", steps: ["On a small ramp you can drop in on, with full pads and a helmet.", "Ride up the ramp toward the coping with enough speed to reach the top.", "Lift the front wheels and set the middle of the board on the coping, front wheels over the deck.", "Press the tail to lift the front wheels back over the coping.", "Roll back down the ramp backward (fakie), weight centered, knees bent."], fixes: [["The front wheels hang up on the coping", "Press the tail more firmly before rolling back."], ["I don't reach the coping", "Pump the ramp to gain speed."]], sci: "You need enough motion energy at the bottom to rise to the coping: ½·m·v² must be at least m·g·h." },
    es: { n: "Rock to fakie", steps: ["En una rampa pequeña en la que ya puedas entrar, con protecciones y casco.", "Sube por la rampa hacia el coping con rapidez para llegar arriba.", "Sube las ruedas de adelante y apoya el centro de la tabla en el coping, con las ruedas delanteras sobre la plataforma.", "Presiona la cola para pasar las ruedas de adelante de vuelta sobre el coping.", "Baja por la rampa hacia atrás (fakie), peso centrado, rodillas dobladas."], fixes: [["Las ruedas de adelante se atoran en el coping", "Presiona la cola más firme antes de volver."], ["No llego al coping", "Bombea la rampa para ganar rapidez."]], sci: "Necesitas suficiente energía de movimiento abajo para subir al coping: ½·m·v² debe ser al menos m·g·h." } },
  { id: "fall", lv: 1, room: "balance", feet: { f: [0.13, 0, 10], b: [-0.17, 0, 5] },
    en: { n: "Falling safely", steps: ["Practice on grass, in a helmet, wrist guards and pads.", "When you feel yourself going, crouch low: you have less far to fall.", "Do not catch yourself with locked, straight arms.", "Roll onto your side or shoulder, or slide on your knee pads.", "Step off the board on purpose when a trick goes wrong. That is a skill too."], fixes: [["I always put my hands out", "Practice rolling on grass slowly, many times, until it feels natural."], ["I'm scared of falling", "That is a normal, useful signal. Break the trick into smaller steps."]], sci: "Rolling and sliding spread the stop over more time and more of your body, so the force on any one place is smaller." },
    es: { n: "Caer con seguridad", steps: ["Practica en el pasto, con casco, muñequeras y protecciones.", "Cuando sientas que te caes, agáchate: caes desde menos altura.", "No te sostengas con los brazos rectos y rígidos.", "Rueda sobre tu lado o tu hombro, o deslízate sobre las rodilleras.", "Bájate de la tabla a propósito cuando un truco sale mal. Eso también es una habilidad."], fixes: [["Siempre pongo las manos", "Practica rodar en el pasto despacio, muchas veces, hasta que salga natural."], ["Me da miedo caer", "Es una señal normal y útil. Divide el truco en pasos más pequeños."]], sci: "Rodar y deslizarse reparten la parada en más tiempo y más partes del cuerpo, así la fuerza en un solo lugar es menor." } }
],
MORE: [{"id": "carve", "lv": 2, "room": "balance", "feet": {"f": [0.15, 0, 10], "b": [-0.17, 0, 5]}, "arrows": [{"from": [0.3, 0], "to": [0.3, 0.25], "curve": 1}], "pre": ["stance", "push", "stop"], "en": {"n": "Carving", "steps": ["Helmet on. Find a wide, smooth, flat place with no cars, like an empty court.", "Push to a slow, steady roll. Feet over the bolts, knees bent.", "Press gently with your toes. The board turns toward the toe side.", "Let the turn finish, then press gently with your heels. The board turns toward the heel side.", "Lean your whole body into each turn, ankles to shoulders, not just your hips.", "Link the turns in a smooth S shape. Make them long and slow at first."], "fixes": [["The board barely turns", "Press a little harder on the edge and lean your shoulders into the turn."], ["I wobble when I switch sides", "Pass through the middle slowly, with both feet flat, before you press the other edge."], ["I'm going too fast", "Make each turn longer and wider. Carving uphill a little slows you down too."]], "sci": "Tilting the deck squeezes the bushings, so the trucks steer the wheels. The wheels' grip pushes you toward the middle of the turn, and leaning in balances it: tan θ = v²/(gR), so a faster or tighter turn needs more lean."}, "es": {"n": "Carving (curvas largas)", "steps": ["Ponte el casco. Busca un lugar ancho, liso y plano, sin autos, como una cancha vacía.", "Empuja hasta rodar despacio y parejo. Pies sobre los tornillos, rodillas dobladas.", "Presiona suave con los dedos. La tabla gira hacia el lado de los dedos.", "Deja que termine el giro y presiona suave con los talones. La tabla gira hacia el lado de los talones.", "Inclina todo el cuerpo en cada giro, de los tobillos a los hombros, no solo la cadera.", "Une los giros en forma de S suave. Al principio, hazlos largos y lentos."], "fixes": [["La tabla casi no gira", "Presiona un poco más el borde e inclina los hombros hacia el giro."], ["Me tambaleo al cambiar de lado", "Pasa por el centro despacio, con los dos pies planos, antes de presionar el otro borde."], ["Voy muy rápido", "Haz cada giro más largo y ancho. Hacer la curva un poco cuesta arriba también te frena."]], "sci": "Al inclinar la tabla se aprietan los bujes y los ejes dirigen las ruedas. El agarre de las ruedas te empuja hacia el centro del giro, y al inclinarte lo equilibras: tan θ = v²/(gR); un giro más rápido o más cerrado pide más inclinación."}}, {"id": "pump", "lv": 3, "room": "ramp", "feet": {"f": [0.15, 0, 5], "b": [-0.2, 0, 5]}, "pre": ["kickturn", "dropin"], "en": {"n": "Pumping", "steps": ["Use a small ramp or a smooth bowl, with full pads and a helmet.", "Roll back and forth on the lower part of the ramp first, with your feet over the bolts.", "As you come up near the top of your ride, crouch: bend your knees low.", "As you pass through the curve at the bottom, push down through your feet and stand up taller.", "Crouch again as you rise up the other side. Then stand up again through the curve.", "Keep the rhythm, like pumping a swing. Each pass takes you a little higher."], "fixes": [["I slow down anyway", "Check your timing: stand up in the curve, not on the flat part or near the top."], ["I lose balance when I stand up", "Stand up smoothly, with your weight centered over both feet."]], "sci": "Standing up in the curve raises your body against the extra push the ramp gives you there, so your legs do work and add energy. Crouching near the top, where that push is small, costs little. More energy at the bottom means a higher ride: ½·m·v² = m·g·h."}, "es": {"n": "Bombear", "steps": ["Usa una rampa pequeña o un bowl liso, con protecciones y casco.", "Primero rueda de ida y vuelta en la parte baja de la rampa, con los pies sobre los tornillos.", "Al subir cerca de lo más alto de tu recorrido, agáchate: dobla bien las rodillas.", "Al pasar por la curva de abajo, empuja hacia abajo con los pies y párate más alto.", "Agáchate otra vez al subir por el otro lado. Luego párate otra vez en la curva.", "Sigue el ritmo, como al columpiarte. Cada pasada te lleva un poco más alto."], "fixes": [["Igual voy perdiendo rapidez", "Revisa el momento: párate en la curva, no en la parte plana ni cerca de arriba."], ["Pierdo el equilibrio al pararme", "Párate suave, con el peso centrado sobre los dos pies."]], "sci": "Al pararte en la curva levantas tu cuerpo contra el empuje extra que ahí te da la rampa, así tus piernas hacen trabajo y suman energía. Agacharte cerca de arriba, donde ese empuje es pequeño, cuesta poco. Más energía abajo te lleva más alto: ½·m·v² = m·g·h."}}, {"id": "fakie", "lv": 2, "room": "balance", "feet": {"f": [0.13, 0, 10], "b": [-0.17, 0, 5]}, "arrows": [{"from": [-0.1, 0], "to": [-0.38, 0]}], "pre": ["stance", "push", "stop"], "en": {"n": "Riding fakie", "steps": ["Helmet on. Find a smooth, flat place with no cars.", "Stand in your normal stance, feet over the bolts. Fakie means rolling backward: the tail goes first.", "Hold a wall or a friend's hand and give a gentle push so you roll backward slowly.", "Turn your head and look over your back shoulder, where you are going.", "Keep your knees bent and your weight centered over both feet.", "To stop, let the board slow down and step off. Then try a little faster."], "fixes": [["I feel like I'm falling backward", "Bend your knees more and keep your weight over the middle of the board, not over the tail."], ["I can't see where I'm going", "Turn your head first. Your shoulders can stay mostly where they are."]], "sci": "The wheels roll the same both ways, so the board does not care which end leads. Your stance stays the same; only your view changes, so looking where you go keeps your balance."}, "es": {"n": "Rodar en fakie", "steps": ["Ponte el casco. Busca un lugar liso y plano, sin autos.", "Párate en tu postura normal, pies sobre los tornillos. Fakie es rodar hacia atrás: la cola va primero.", "Sujétate de una pared o de la mano de alguien y empuja suave para rodar hacia atrás despacio.", "Gira la cabeza y mira por encima del hombro de atrás, adonde vas.", "Rodillas dobladas y el peso centrado sobre los dos pies.", "Para frenar, deja que la tabla vaya más lento y bájate. Luego prueba un poco más rápido."], "fixes": [["Siento que me caigo hacia atrás", "Dobla más las rodillas y deja tu peso sobre el centro de la tabla, no sobre la cola."], ["No veo adónde voy", "Gira primero la cabeza. Los hombros pueden quedarse casi donde están."]], "sci": "Las ruedas giran igual en los dos sentidos, así a la tabla no le importa qué punta va primero. Tu postura es la misma; solo cambia lo que ves, por eso mirar adonde vas te ayuda a mantener el equilibrio."}}, {"id": "nosemanual", "lv": 3, "room": "balance", "feet": {"f": [0.3, 0, 5], "b": [-0.1, 0, 5]}, "pre": ["manual"], "en": {"n": "Nose manual", "steps": ["Get a steady manual first. Helmet on, on smooth, flat ground.", "Roll slowly. Move your front foot onto the nose and your back foot to just behind the back bolts.", "Shift your weight forward until it is right over the front wheels.", "The back wheels lift. Keep the nose just off the ground.", "Use small moves of your arms and hips to stay balanced. Look ahead, not down.", "Put the back wheels down before you lose it. Try for a short distance first."], "fixes": [["The nose scrapes", "Your weight is too far forward. Move it back a little."], ["The back wheels won't lift", "Move your front foot closer to the end of the nose and lean forward a little more."]], "sci": "A nose manual is a manual on the other axle: the line of your weight falls right over the front wheels. The nose is shorter than the tail on many boards, so the balance window is smaller."}, "es": {"n": "Nose manual", "steps": ["Primero ten un manual firme. Con casco, en suelo liso y plano.", "Rueda despacio. Lleva el pie de adelante a la nariz y el de atrás justo detrás de los tornillos traseros.", "Lleva tu peso adelante hasta que quede justo sobre las ruedas de adelante.", "Suben las ruedas de atrás. La nariz queda justo sobre el suelo.", "Usa pequeños movimientos de brazos y cadera para mantenerte. Mira adelante, no abajo.", "Baja las ruedas de atrás antes de perderlo. Prueba primero una distancia corta."], "fixes": [["La nariz raspa", "Tu peso está muy adelante. Muévelo un poco atrás."], ["Las ruedas de atrás no suben", "Lleva el pie de adelante más cerca de la punta de la nariz e inclínate un poco más adelante."]], "sci": "Un nose manual es un manual sobre el otro eje: la línea de tu peso cae justo sobre las ruedas de adelante. En muchas tablas la nariz es más corta que la cola, así el espacio para el equilibrio es menor."}}, {"id": "bs180", "lv": 3, "room": "flip", "feet": {"f": [0.1, 0, 10], "b": [-0.3, 0, 5]}, "arrows": [{"from": [0.3, 0], "to": [0.3, -0.25], "curve": 1}], "pre": ["ollie", "fakie"], "en": {"n": "Backside 180", "steps": ["Get a steady ollie and a steady fakie roll first. Helmet on, on smooth, flat ground.", "Before you pop, wind your shoulders a little toward your front, the toe side.", "Pop an ollie and turn your shoulders the other way, so your back leads.", "Your hips and the board follow your shoulders, half a turn. Look over your back shoulder for the ground.", "Land rolling backward (fakie), with both feet over the bolts and your knees bent."], "fixes": [["I only turn a quarter", "Wind up more before the pop, and turn your head first."], ["I can't see where I'll land", "That is normal for backside spins. Look over your back shoulder as soon as you pop."], ["The board turns but I don't", "Turn your shoulders and hips together, and pop straight up."]], "sci": "Your feet push on the ground to start the spin, a torque, before the wheels leave it. In the air nothing can add spin, so a backside 180 turns the same amount as a frontside 180; only the direction changes."}, "es": {"n": "Backside 180", "steps": ["Primero ten un ollie firme y rueda en fakie con calma. Con casco, en suelo liso y plano.", "Antes del golpe, gira un poco los hombros hacia tu frente, el lado de los dedos.", "Haz un ollie y gira los hombros al otro lado, para que tu espalda guíe.", "La cadera y la tabla siguen a los hombros, media vuelta. Busca el suelo por encima del hombro de atrás.", "Aterriza rodando hacia atrás (fakie), con los dos pies sobre los tornillos y las rodillas dobladas."], "fixes": [["Solo giro un cuarto", "Gira más los hombros antes del golpe y gira primero la cabeza."], ["No veo dónde voy a caer", "Es normal en los giros backside. Mira por encima del hombro de atrás en cuanto saltes."], ["La tabla gira pero yo no", "Gira hombros y cadera juntos, y salta recto hacia arriba."]], "sci": "Tus pies empujan el suelo para empezar el giro, un torque, antes de que las ruedas lo dejen. En el aire nada puede sumar giro, así un backside 180 gira lo mismo que un frontside 180; solo cambia la dirección."}}, {"id": "axlestall", "lv": 4, "room": "ramp", "feet": {"f": [0.15, 0, 5], "b": [-0.2, 0, 5]}, "pre": ["dropin", "kickturn", "rockfakie"], "en": {"n": "Axle stall", "steps": ["Use a small ramp you can already drop in on and rock to fakie on, with full pads and a helmet.", "Ride up toward the coping with enough speed to just reach the top.", "Near the top, press the tail a little and turn, like a kickturn, so the board ends up along the coping.", "Set the back truck on the coping, then the front truck. Both trucks rest on the coping, the board along it.", "Pause there with your weight centered between your feet, knees bent.", "Press the tail a little, turn the nose back toward the ramp, and drop back in with your weight forward, like a drop-in."], "fixes": [["I slide off the coping", "Come up with a little less speed and set the back truck down first, firmly."], ["I hang up when I drop back in", "Lift the front wheels clear of the coping before you turn, and lean forward as you go."]], "sci": "At the top your motion energy has become stored energy, m·g·h, and you stop for a moment. Dropping back in turns it back into motion: from a height h, v = √(2gh), less a little lost to friction."}, "es": {"n": "Axle stall", "steps": ["Usa una rampa pequeña en la que ya puedas entrar y hacer rock to fakie, con protecciones y casco.", "Sube hacia el coping con la rapidez justa para llegar arriba.", "Cerca de arriba, presiona un poco la cola y gira, como un kickturn, para que la tabla quede a lo largo del coping.", "Apoya el eje de atrás en el coping y luego el de adelante. Los dos ejes descansan en el coping, la tabla a lo largo.", "Haz una pausa con el peso centrado entre los pies, rodillas dobladas.", "Presiona un poco la cola, gira la nariz hacia la rampa y vuelve a entrar con el peso adelante, como al hacer drop in."], "fixes": [["Me resbalo del coping", "Sube con un poco menos de rapidez y apoya primero el eje de atrás, firme."], ["Me atoro al volver a entrar", "Pasa las ruedas de adelante sobre el coping antes de girar e inclínate adelante al bajar."]], "sci": "Arriba, tu energía de movimiento se volvió energía guardada, m·g·h, y te detienes un momento. Al volver a entrar se vuelve movimiento otra vez: desde una altura h, v = √(2gh), menos un poco que se pierde por fricción."}}, {"id": "noseslide", "lv": 4, "room": "grind", "feet": {"f": [0.3, 0, 5], "b": [-0.12, 0, 5]}, "pre": ["ollie", "nosemanual", "boardslide"], "en": {"n": "Noseslide", "steps": ["Start on a low waxed curb, with a helmet and pads. Never a handrail or stairs.", "Roll alongside the curb, close and nearly parallel, at a steady, medium speed.", "Ollie and turn the board a quarter turn so the nose lands on top of the curb's edge.", "Keep your front foot on the nose, pressing down, and your weight over it. The tail stays in the air.", "Look at the end of the curb and keep your knees bent.", "At the end, turn the board back a quarter turn and land rolling, feet over the bolts."], "fixes": [["The tail drops and I stop", "Keep more weight on your front foot, over the nose."], ["The nose slips off the curb", "Ollie a little higher and land with the nose fully on top of the edge."], ["I stop on the curb", "Come in a little faster, or add wax."]], "sci": "Pressing the nose puts nearly all your weight on it, and the friction is f = μN. Wax lowers μ, so the same weight slides farther before friction stops you."}, "es": {"n": "Noseslide", "steps": ["Empieza en un bordillo bajo con cera, con casco y protecciones. Nunca un pasamanos ni escaleras.", "Rueda al lado del bordillo, cerca y casi paralelo, a una rapidez media y pareja.", "Haz un ollie y gira la tabla un cuarto de vuelta para que la nariz caiga sobre el borde del bordillo.", "Deja el pie de adelante en la nariz, presionando, y tu peso sobre él. La cola queda en el aire.", "Mira el final del bordillo y deja las rodillas dobladas.", "Al final, gira la tabla de vuelta un cuarto y aterriza rodando, con los pies sobre los tornillos."], "fixes": [["La cola baja y me detengo", "Deja más peso en el pie de adelante, sobre la nariz."], ["La nariz se resbala del bordillo", "Haz el ollie un poco más alto y cae con la nariz bien encima del borde."], ["Me detengo en el bordillo", "Entra un poco más rápido o pon más cera."]], "sci": "Al presionar la nariz, casi todo tu peso queda en ella, y la fricción es f = μN. La cera baja μ, así el mismo peso se desliza más lejos antes de que la fricción te detenga."}}, {"id": "varial", "lv": 5, "room": "flip", "feet": {"f": [0.05, -0.02, 30], "b": [-0.34, 0.05, 0]}, "arrows": [{"from": [-0.36, 0.05], "to": [-0.3, -0.2], "curve": 1}, {"from": [0.07, 0], "to": [0.33, 0.1]}], "pre": ["shove", "kickflip"], "en": {"n": "Varial kickflip", "steps": ["Advanced: learn this only after your pop shove-it and kickflip are both steady. Helmet on, on smooth, flat ground.", "Back foot on the tail, toes near the toe-side edge, ready to scoop. Front foot angled, just behind the front bolts.", "Pop the tail and scoop it behind you with your back foot, like a pop shove-it.", "At the same time, flick your front foot off the toe-side corner of the nose, a little forward, like a small kickflip.", "Jump up and lift your knees. The board spins half a turn flat and flips once under you.", "When you see the grip tape again, catch it with your back foot, then your front foot, and land over the bolts."], "fixes": [["It only shoves and doesn't flip", "Flick the front foot off the very corner of the nose."], ["It flips but only turns a quarter", "Scoop harder with the back foot."], ["The board flies away", "Jump straight up, and flick a little less."]], "sci": "The scoop is a torque about the up-down axis and the flick is a torque about the long axis, so the board spins both ways at once: half a turn flat and a full flip."}, "es": {"n": "Varial kickflip", "steps": ["Avanzado: apréndelo solo cuando tu pop shove-it y tu kickflip ya sean firmes. Con casco, en suelo liso y plano.", "Pie de atrás en la cola, con los dedos cerca del borde del lado de los dedos, listo para empujar. Pie de adelante en ángulo, justo detrás de los tornillos delanteros.", "Golpea la cola y empújala hacia atrás con el pie de atrás, como un pop shove-it.", "Al mismo tiempo, raspa con el pie de adelante la esquina de la nariz del lado de los dedos, un poco hacia adelante, como un kickflip pequeño.", "Salta y sube las rodillas. La tabla gira media vuelta plana y da una vuelta completa bajo ti.", "Cuando veas otra vez la lija, atrápala con el pie de atrás, luego el de adelante, y aterriza sobre los tornillos."], "fixes": [["Solo gira plana y no da la vuelta", "Raspa justo la esquina de la nariz con el pie de adelante."], ["Da la vuelta pero gira solo un cuarto", "Empuja más fuerte con el pie de atrás."], ["La tabla sale volando", "Salta recto hacia arriba y raspa un poco menos."]], "sci": "El empuje del pie de atrás es un torque sobre el eje vertical y el raspón es un torque sobre el eje largo, así la tabla gira de las dos formas a la vez: media vuelta plana y una vuelta completa."}}, {"id": "tre", "lv": 5, "room": "flip", "feet": {"f": [0.05, -0.02, 35], "b": [-0.36, 0.06, 0]}, "arrows": [{"from": [-0.38, 0.06], "to": [-0.3, -0.22], "curve": 1}, {"from": [0.07, 0], "to": [0.33, 0.1]}], "pre": ["varial", "kickflip", "shove"], "en": {"n": "360 flip (tre flip)", "steps": ["Advanced: learn this only after your varial kickflip is steady. Helmet on, on smooth, flat ground, never down stairs.", "Back foot on the tail, toes near the toe-side edge, ready to scoop. Front foot angled, just behind the front bolts.", "Pop and scoop the tail hard behind you and a little down with your back foot. The back foot does most of the work.", "Flick your front foot lightly off the toe-side corner of the nose, a little forward.", "Jump up and lift your knees high. The board spins a full turn flat and flips once under you.", "When you see the grip tape again, catch it with your back foot, then your front foot, and land over the bolts with bent knees."], "fixes": [["The board only turns half way", "Scoop harder with the back foot, with snap from the ankle."], ["It flips too much", "Flick lighter with the front foot. Let the back foot lead."], ["The board shoots out in front", "Jump straight up and scoop more behind you, less forward."]], "sci": "The scoop spins the board a full turn about the up-down axis while the flick spins it once about its long axis. Both spins start before the board leaves your feet; in the air nothing adds more."}, "es": {"n": "360 flip (tre flip)", "steps": ["Avanzado: apréndelo solo cuando tu varial kickflip ya sea firme. Con casco, en suelo liso y plano, nunca escaleras abajo.", "Pie de atrás en la cola, con los dedos cerca del borde del lado de los dedos, listo para empujar. Pie de adelante en ángulo, justo detrás de los tornillos delanteros.", "Golpea y empuja la cola fuerte hacia atrás y un poco hacia abajo con el pie de atrás. El pie de atrás hace casi todo el trabajo.", "Raspa suave con el pie de adelante la esquina de la nariz del lado de los dedos, un poco hacia adelante.", "Salta y sube bien las rodillas. La tabla gira una vuelta entera plana y da una vuelta completa bajo ti.", "Cuando veas otra vez la lija, atrápala con el pie de atrás, luego el de adelante, y aterriza sobre los tornillos con las rodillas dobladas."], "fixes": [["La tabla gira solo media vuelta", "Empuja más fuerte con el pie de atrás, con golpe del tobillo."], ["Da demasiadas vueltas", "Raspa más suave con el pie de adelante. Deja que guíe el pie de atrás."], ["La tabla se va adelante", "Salta recto hacia arriba y empuja más hacia atrás, menos hacia adelante."]], "sci": "El empuje gira la tabla una vuelta entera sobre el eje vertical mientras el raspón la hace dar una vuelta sobre su eje largo. Los dos giros empiezan antes de que la tabla deje tus pies; en el aire nada suma más."}}],
FAQ: [{"id": "regular-or-goofy", "cat": "start", "room": "tricks", "trick": "stance", "en": {"q": "Am I regular or goofy?", "a": "Regular means your left foot goes in front. Goofy means your right foot goes in front. Both are normal, and neither one is better. To find yours, stand on the board on grass or carpet so it cannot roll. Try each foot in front. The one that feels steady and easy is your front foot. Still not sure? Try both for a few days. From here on, think front foot and back foot."}, "es": {"q": "¿Soy regular o goofy?", "a": "Regular quiere decir que el pie izquierdo va adelante. Goofy quiere decir que el pie derecho va adelante. Las dos formas son normales, y ninguna es mejor. Para saber cuál es la tuya, párate en la patineta sobre pasto o alfombra, así no rueda. Prueba con cada pie adelante. El que se siente firme y cómodo es tu pie de adelante. ¿Todavía no sabes? Prueba las dos formas unos días. Desde ahora, piensa en pie de adelante y pie de atrás."}}, {"id": "where-to-learn", "cat": "start", "room": "tricks", "trick": "push", "en": {"q": "Where should I learn to ride?", "a": "Pick a place that is smooth, flat, dry and away from cars. An empty basketball court, a quiet smooth path or the flat part of a skatepark all work. First, stand on the board on grass or carpet so it cannot roll far. Feel your balance there. Then roll slowly on smooth ground. A small pebble can stop a wheel suddenly, so look ahead and sweep the spot if you can. Children should have a grown-up nearby."}, "es": {"q": "¿Dónde aprendo a patinar?", "a": "Busca un lugar liso, plano, seco y lejos de los carros. Sirve una cancha de básquetbol vacía, un camino liso y tranquilo o la parte plana de un skatepark. Primero, párate en la patineta sobre pasto o alfombra, así no rueda lejos. Siente tu equilibrio ahí. Después, rueda despacio en un piso liso. Una piedrita puede frenar una rueda de golpe, así que mira hacia adelante y barre el lugar si puedes. Los niños deben tener a un adulto cerca."}}, {"id": "how-old", "cat": "start", "en": {"q": "How old is old enough to skate?", "a": "The American Academy of Pediatrics says children under 5 should not ride skateboards. At that age, balance and the skill of falling safely are still growing. It says children 6 to 10 should skate with an adult watching. Older kids, teens and adults can start at any age. Whatever your age, a helmet that fits and a smooth place away from cars come first."}, "es": {"q": "¿Desde qué edad se puede patinar?", "a": "La Academia Americana de Pediatría dice que los niños menores de 5 años no deben andar en patineta. A esa edad, el equilibrio y la habilidad de caer con cuidado todavía están creciendo. También dice que los niños de 6 a 10 años deben patinar con un adulto mirando. Los niños mayores, los jóvenes y los adultos pueden empezar a cualquier edad. Tengas la edad que tengas, primero va un casco que te quede bien y un lugar liso lejos de los carros."}}, {"id": "learn-first", "cat": "start", "room": "tricks", "trick": "stop", "en": {"q": "What should I learn first?", "a": "Learn these in order. First, stand still on the board on grass or carpet, with your front foot over the front bolts. Next, push: put your back foot on the ground, take small steps, then put it back on the board. Then learn to stop: lift your back foot and let its sole drag gently on the ground. Then turn by leaning toward your toes or your heels. Practice falling small early too. Tricks can wait until rolling feels calm."}, "es": {"q": "¿Qué aprendo primero?", "a": "Aprende esto en orden. Primero, párate quieto en la patineta sobre pasto o alfombra, con el pie de adelante sobre los tornillos de adelante. Después, empuja: pon el pie de atrás en el piso, da pasos cortos y vuelve a subirlo a la patineta. Luego aprende a frenar: baja el pie de atrás y deja que la suela roce suavemente el piso. Luego gira inclinándote hacia los dedos o hacia los talones. Practica también caer con cuidado desde el principio. Los trucos pueden esperar hasta que rodar se sienta tranquilo."}}, {"id": "first-board", "cat": "gear", "room": "build", "en": {"q": "What kind of board should I get first?", "a": "A complete, meaning a board that comes already put together, is a fine start. Many first decks are about 7.5 to 8.25 inches (19 to 21 cm) wide. Smaller riders often like the narrower ones. Most decks are made of seven thin layers of maple. Check that the wheels spin freely and the trucks turn when you lean. Toy boards with hard plastic wheels often slip and rattle. The Build a board room shows how the parts fit together."}, "es": {"q": "¿Qué patineta compro primero?", "a": "Una completa, o sea una patineta que ya viene armada, es un buen comienzo. Muchas tablas para empezar miden entre 7.5 y 8.25 pulgadas (de 19 a 21 cm) de ancho, más o menos. A los niños más pequeños muchas veces les gustan las más angostas. Casi todas las tablas tienen siete capas delgadas de maple. Revisa que las ruedas giren libres y que los trucks giren cuando te inclinas. Las patinetas de juguete con ruedas de plástico duro suelen resbalar y hacer ruido. La sala Arma una patineta muestra cómo se juntan las partes."}}, {"id": "soft-or-hard-wheels", "cat": "gear", "room": "build", "en": {"q": "Should I get soft wheels or hard wheels?", "a": "Wheel hardness is measured on the durometer A scale. Skateboard wheels go from about 78A, which is soft, to about 101A, which is hard. Soft wheels grip well, feel smooth and roll over rough ground and small cracks. They are good for sidewalks and cruising. Hard wheels slide more easily and feel fast on smooth skatepark concrete. For a first board on mixed ground, wheels on the softer side are often easier."}, "es": {"q": "¿Compro ruedas blandas o duras?", "a": "La dureza de las ruedas se mide en la escala de durómetro A. Las ruedas de patineta van de unos 78A, que son blandas, a unos 101A, que son duras. Las ruedas blandas agarran bien, se sienten suaves y pasan por piso áspero y grietas pequeñas. Son buenas para la banqueta y para pasear. Las ruedas duras se deslizan con más facilidad y se sienten rápidas en el concreto liso del skatepark. Para una primera patineta en pisos variados, las ruedas más blandas suelen ser más fáciles."}}, {"id": "truck-tightness", "cat": "gear", "room": "build", "en": {"q": "How tight should my trucks be?", "a": "The big nut in the middle of each truck, the kingpin nut, sets how easily the board turns. Looser trucks turn with a small lean but can feel wobbly. Tighter trucks feel steady but need a bigger lean to turn. Start in the middle. Turn the nut a quarter turn at a time, then ride and feel the change. Never loosen it so far that the nut barely holds on. Set both trucks about the same."}, "es": {"q": "¿Qué tan apretados deben estar los trucks?", "a": "La tuerca grande en el centro de cada truck, la tuerca del kingpin, decide qué tan fácil gira la patineta. Los trucks flojos giran con poca inclinación, pero se pueden sentir tambaleantes. Los trucks apretados se sienten firmes, pero necesitas inclinarte más para girar. Empieza en un punto medio. Gira la tuerca un cuarto de vuelta cada vez, luego rueda y siente el cambio. Nunca la aflojes tanto que la tuerca apenas se sostenga. Deja los dos trucks más o menos iguales."}}, {"id": "shoes", "cat": "gear", "en": {"q": "What shoes should I wear?", "a": "Wear sneakers with a flat rubber sole, such as canvas or suede ones. A flat sole lets you feel the board and grips the grip tape. Skip sandals, boots with thick heels and running shoes with big curved soles. Tie your laces well and tuck in the ends so they cannot catch. Ollies and flip tricks rub the top of your shoe, so that spot may wear out faster. That is normal."}, "es": {"q": "¿Qué zapatos uso?", "a": "Usa tenis con suela de hule plana, por ejemplo de lona o de gamuza. Una suela plana te deja sentir la patineta y se agarra bien a la lija. Evita las sandalias, las botas con tacón grueso y los tenis para correr con suela muy curva. Amarra bien las agujetas y mete las puntas para que no se atoren. Los ollies y los trucos de flip rozan la parte de arriba del zapato, así que esa parte se puede gastar más rápido. Eso es normal."}}, {"id": "replace-parts", "cat": "gear", "room": "build", "en": {"q": "When should I replace grip tape or bearings?", "a": "Replace grip tape when it feels smooth and your shoes slip, or when it peels up at the edges. Scrubbing it with a stiff brush can help first. Bearings need care when the wheels stop spinning quickly, grind, squeak or feel rough. Sometimes cleaning them fixes the problem. If they stay rough or rusty, replace them. The ABEC number on bearings tells how precisely they are made, not how fast they go."}, "es": {"q": "¿Cuándo cambio la lija o los baleros?", "a": "Cambia la lija cuando se sienta lisa y tus zapatos resbalen, o cuando se despegue en las orillas. Antes, tallarla con un cepillo duro puede ayudar. Los baleros necesitan cuidado cuando las ruedas dejan de girar pronto, raspan, rechinan o se sienten ásperas. A veces limpiarlos arregla el problema. Si siguen ásperos u oxidados, cámbialos. El número ABEC de los baleros dice qué tan precisos están hechos, no qué tan rápido van."}}, {"id": "helmet-fit", "cat": "safety", "en": {"q": "How should my helmet fit?", "a": "A good helmet sits level on your head and covers your forehead. It feels snug, not tight, and it does not rock when you shake your head. Always buckle the strap. About one finger should fit between the strap and your chin. Wear it every time, even for a short ride. Many helmets are made for one big hit, so replace yours after a hard crash, even if it looks fine. Look for a label saying it meets a safety standard."}, "es": {"q": "¿Cómo me debe quedar el casco?", "a": "Un buen casco queda derecho en la cabeza y te cubre la frente. Se siente ajustado, pero no apretado, y no se mueve cuando sacudes la cabeza. Siempre abrocha la correa. Debe caber más o menos un dedo entre la correa y tu barbilla. Úsalo cada vez, aunque sea un paseo corto. Muchos cascos están hechos para un solo golpe fuerte, así que cámbialo después de una caída dura, aunque se vea bien. Busca una etiqueta que diga que cumple una norma de seguridad."}}, {"id": "wrist-guards", "cat": "safety", "trick": "fall", "en": {"q": "Do I really need wrist guards?", "a": "They help a lot, especially while you learn. Wrist injuries are among the most common skateboarding injuries, because people reach out with their hands when they fall. Wrist guards have a stiff piece that helps protect the wrist when a hand hits the ground. Knee pads and elbow pads help too. Knee pads also let you slide safely down a ramp. Pads that fit snugly and stay in place work best."}, "es": {"q": "¿De verdad necesito muñequeras?", "a": "Ayudan mucho, sobre todo mientras aprendes. Las lesiones de muñeca están entre las más comunes al andar en patineta, porque al caer la gente estira las manos. Las muñequeras tienen una pieza firme que ayuda a proteger la muñeca cuando la mano pega en el piso. Las rodilleras y las coderas también ayudan. Con las rodilleras, además, puedes deslizarte con seguridad por una rampa. Las protecciones que quedan ajustadas y no se mueven funcionan mejor."}}, {"id": "how-to-fall", "cat": "safety", "room": "tricks", "trick": "fall", "en": {"q": "How do I fall without getting hurt?", "a": "Falling is part of learning, and you can practice it. When you feel a fall coming, crouch low so you have less distance to fall. Try not to catch yourself with straight, locked arms. Instead, let your body roll onto your side or shoulder. On a ramp, drop to your knee pads and slide down. Practice these moves slowly on grass first. Falling small is a skill, just like any trick."}, "es": {"q": "¿Cómo me caigo sin lastimarme?", "a": "Caerse es parte de aprender, y lo puedes practicar. Cuando sientas que te vas a caer, agáchate para tener menos distancia hasta el piso. Trata de no detenerte con los brazos estirados y rígidos. Mejor, deja que tu cuerpo ruede hacia un lado o sobre el hombro. En una rampa, cae sobre las rodilleras y deslízate hacia abajo. Practica estos movimientos despacio, primero en el pasto. Caer con cuidado es una habilidad, igual que cualquier truco."}}, {"id": "wet-ground", "cat": "safety", "en": {"q": "Can I skate when the ground is wet?", "a": "It is best not to. Wet urethane wheels lose their grip, so the board can slip out with no warning. Water also gets inside the bearings and makes them rust, so they spin rough or stop. A wooden deck can soak up water and get weaker. Wait until the ground is fully dry. If your board gets wet, dry it with a towel and let it air-dry before you ride again."}, "es": {"q": "¿Puedo patinar si el piso está mojado?", "a": "Mejor no. Las ruedas de uretano mojadas pierden agarre, y la patineta se puede resbalar sin aviso. El agua también entra a los baleros y los oxida, así que giran ásperos o se detienen. Una tabla de madera puede absorber agua y debilitarse. Espera a que el piso esté bien seco. Si tu patineta se moja, sécala con una toalla y déjala secar al aire antes de volver a usarla."}}, {"id": "near-cars", "cat": "safety", "en": {"q": "Is it okay to skate in the street or near cars?", "a": "No. Drivers may not see a skateboarder, and a board cannot stop quickly. Never skate in traffic, down hills where cars drive, or out of a driveway into the street. Never hold onto a car, bike or any moving vehicle to get pulled along. Choose a skatepark, an empty court or a smooth path away from cars. When you need to cross a street, step off, pick up your board and walk."}, "es": {"q": "¿Está bien patinar en la calle o cerca de los carros?", "a": "No. Los conductores pueden no ver a quien va en patineta, y una patineta no frena rápido. Nunca patines entre el tráfico, en bajadas por donde pasan carros ni saliendo de una cochera hacia la calle. Nunca te agarres de un carro, una bici ni ningún vehículo para que te jale. Escoge un skatepark, una cancha vacía o un camino liso lejos de los carros. Cuando tengas que cruzar una calle, bájate, levanta tu patineta y camina."}}, {"id": "ollie-time", "cat": "tricks", "room": "ollie", "trick": "ollie", "en": {"q": "How long does it take to learn an ollie?", "a": "It takes most people many practice days, often weeks, and sometimes longer. Everyone learns at a different pace, and that is fine. The ollie has several parts: snap the tail, slide the front foot up, jump and level the board. Practice standing still on grass or carpet first. Then try it while rolling slowly. Short practice on most days often works better than one long day. Every small hop is progress."}, "es": {"q": "¿Cuánto tiempo toma aprender el ollie?", "a": "A la mayoría le toma muchos días de práctica, muchas veces semanas, y a veces más. Cada persona aprende a su ritmo, y eso está bien. El ollie tiene varias partes: pegar con la cola, subir deslizando el pie de adelante, saltar y emparejar la patineta. Practica primero quieto sobre pasto o alfombra. Después pruébalo rodando despacio. Practicar un rato corto casi todos los días suele funcionar mejor que un solo día largo. Cada saltito pequeño es un avance."}}, {"id": "board-shoots-out", "cat": "tricks", "room": "ollie", "trick": "ollie", "en": {"q": "Why does my board roll away or shoot out in front of me?", "a": "Usually your weight is too far back. When you lean back, the board rolls forward without you. Keep your shoulders over the board and your knees bent. On an ollie, the board shoots out when your back foot pushes forward instead of straight down. It also happens when you jump backward. Snap the tail down, then jump straight up. Keep your shoulders facing the same way as the board."}, "es": {"q": "¿Por qué mi patineta se me va o sale disparada hacia adelante?", "a": "Casi siempre es porque tu peso está muy atrás. Cuando te echas para atrás, la patineta sigue rodando sin ti. Mantén los hombros sobre la patineta y las rodillas dobladas. En el ollie, la patineta sale disparada cuando el pie de atrás empuja hacia adelante en vez de hacia abajo. También pasa cuando saltas hacia atrás. Pega la cola hacia abajo y luego salta derecho hacia arriba. Mantén los hombros mirando hacia el mismo lado que la patineta."}}, {"id": "kickflip-or-heelflip", "cat": "tricks", "room": "flip", "trick": "kickflip", "en": {"q": "What is the difference between a kickflip and a heelflip?", "a": "Both start like an ollie, and the board spins one full turn under your feet. In a kickflip, the front foot slides up and flicks off the heel-side edge of the nose with the side of the toes. In a heelflip, the front foot flicks off the toe-side edge of the nose with the heel. So the two tricks spin in opposite directions. Learn a steady ollie before trying either one."}, "es": {"q": "¿Cuál es la diferencia entre un kickflip y un heelflip?", "a": "Los dos empiezan como un ollie, y la patineta da una vuelta completa debajo de tus pies. En el kickflip, el pie de adelante sube y golpea la orilla del lado de los talones de la nariz con el costado de los dedos. En el heelflip, el pie de adelante golpea la orilla del lado de los dedos de la nariz con el talón. Por eso los dos trucos giran en direcciones opuestas. Aprende un ollie firme antes de probar cualquiera de los dos."}}, {"id": "stairs-and-rails", "cat": "tricks", "room": "grind", "en": {"q": "When can I try stairs or rails?", "a": "Much later. Stairs and handrails come only after a long time of steady basics: rolling, turning, stopping, falling small and clean ollies. When you are ready to slide on something, start low. A painted curb, a low ledge or a low flat bar at a skatepark comes first. Go higher only in small steps, with a helmet and pads. Skating is not a race. Low tricks done well are real skating."}, "es": {"q": "¿Cuándo puedo probar escaleras o barandales?", "a": "Mucho después. Las escaleras y los barandales vienen solo después de mucho tiempo con lo básico firme: rodar, girar, frenar, caer con cuidado y hacer ollies limpios. Cuando estés listo para deslizarte en algo, empieza bajo. Primero va una orilla pintada, un borde bajo o un tubo bajo y plano en un skatepark. Sube de altura solo poco a poco, con casco y protecciones. Patinar no es una carrera. Los trucos bajos bien hechos también son patinar de verdad."}}, {"id": "feeling-scared", "cat": "tricks", "en": {"q": "I feel scared to try a trick. What can I do?", "a": "Feeling scared is normal. It is your body asking you to slow down and plan. Break the trick into smaller steps. Practice each step standing still on grass or carpet. Try a lower or slower version first. Wear your helmet and pads so a fall stays small. A friend or a grown-up nearby can help. It is fine to stop for the day and come back. Many experienced skaters still feel fear."}, "es": {"q": "Me da miedo probar un truco. ¿Qué puedo hacer?", "a": "Sentir miedo es normal. Es tu cuerpo pidiéndote que vayas más despacio y que planees. Divide el truco en pasos más pequeños. Practica cada paso quieto sobre pasto o alfombra. Prueba primero una versión más baja o más lenta. Usa casco y protecciones para que una caída sea pequeña. Un amigo o un adulto cerca puede ayudar. Está bien parar por hoy y volver otro día. Muchos patinadores con experiencia también sienten miedo."}}, {"id": "taking-turns", "cat": "park", "en": {"q": "How do I take turns at the skatepark?", "a": "Skateparks run on taking turns. Wait until the person before you finishes their run. Before you go, look around and make sure your path is clear. Keep your runs short when it is busy. Do not sit on ramps or ledges, and do not stand where people land. When your turn ends, roll out of the way. Watching others first helps you learn how people move through the park."}, "es": {"q": "¿Cómo tomo turnos en el skatepark?", "a": "En el skatepark todo funciona por turnos. Espera a que la persona antes que tú termine su recorrido. Antes de salir, mira alrededor y revisa que tu camino esté libre. Haz recorridos cortos cuando hay mucha gente. No te sientes en las rampas ni en los bordes, y no te pares donde la gente cae de un truco. Cuando termine tu turno, sal del camino rodando. Mirar a los demás primero te ayuda a aprender cómo se mueve la gente en el parque."}}, {"id": "look-before-drop-in", "cat": "park", "room": "ramp", "trick": "dropin", "en": {"q": "What should I check before I drop in?", "a": "Look at the whole ramp and the flat bottom first. Make sure no one is rolling toward you or standing where you will land. Set your tail on the coping and wait until the path is clear. Let others see that you are next. If two people start at once, one person waits. Learn to drop in on a small ramp first, with a helmet and pads."}, "es": {"q": "¿Qué reviso antes de hacer un drop in?", "a": "Primero mira toda la rampa y la parte plana de abajo. Revisa que nadie venga rodando hacia ti ni esté parado donde vas a llegar. Pon la cola de la patineta en el coping y espera hasta que el camino esté libre. Deja que los demás vean que sigues tú. Si dos personas salen al mismo tiempo, una espera. Aprende el drop in primero en una rampa pequeña, con casco y protecciones."}}, {"id": "what-is-a-snake", "cat": "park", "en": {"q": "What is a snake at the skatepark?", "a": "A snake is someone who cuts in and takes a turn that belongs to someone else. Cutting in can cause crashes and hard feelings. If you are not sure whose turn it is, wait and let the other person go. If you cut in by mistake, say sorry and roll out of the way. Most skaters are kind to beginners who wait their turn."}, "es": {"q": "¿Qué es un snake en el skatepark?", "a": "Un snake es alguien que se mete y toma un turno que le toca a otra persona. Meterse así puede causar choques y enojos. Si no sabes a quién le toca, espera y deja que la otra persona vaya primero. Si te metiste sin querer, pide perdón y sal del camino. La mayoría de los patinadores son amables con los principiantes que esperan su turno."}}, {"id": "busy-times", "cat": "park", "en": {"q": "When is the skatepark less busy?", "a": "Many skateparks are calmer early in the morning. They are often busier after school, in the evening and on weekends. Visit at a few different times and notice what feels best for you. If it is crowded, practice basics in a quiet flat corner, or come back another time. Some parks offer lessons or beginner times. A calmer park can make learning feel easier."}, "es": {"q": "¿Cuándo hay menos gente en el skatepark?", "a": "Muchos skateparks están más tranquilos temprano en la mañana. Suelen tener más gente después de la escuela, en la tarde-noche y los fines de semana. Ve a distintas horas y fíjate cuál se siente mejor para ti. Si hay mucha gente, practica lo básico en una esquina plana y tranquila, o regresa otro día. Algunos parques tienen clases u horarios para principiantes. Un parque más tranquilo puede hacer que aprender se sienta más fácil."}}, {"id": "too-late-to-start", "cat": "adults", "en": {"q": "Am I too old to start skating?", "a": "No. Many people start skateboarding as adults. You can learn to push, turn, stop and do tricks, one step at a time. Adults often bring helpful strengths, like patience, planning and knowing when to rest. Bodies can take longer to heal as we get older, so protection matters even more. Wear a helmet, wrist guards, knee pads and elbow pads. Start on flat ground and enjoy each new step."}, "es": {"q": "¿Ya estoy muy grande para empezar a patinar?", "a": "No. Mucha gente empieza a andar en patineta de adulta. Puedes aprender a empujar, girar, frenar y hacer trucos, paso a paso. Los adultos muchas veces traen fortalezas que ayudan, como la paciencia, la planeación y saber cuándo descansar. Con los años, el cuerpo puede tardar más en sanar, así que la protección importa todavía más. Usa casco, muñequeras, rodilleras y coderas. Empieza en piso plano y disfruta cada paso nuevo."}}, {"id": "adult-pace", "cat": "adults", "room": "balance", "en": {"q": "How should I pace my practice as an adult?", "a": "Warm up first with a few minutes of walking, gentle stretches and easy rolling. Shorter sessions a few times a week often work well. Stop while you still feel fresh, because tired legs make falls more likely. Hip pads or padded shorts can soften falls on your side. Learn one skill until it feels steady before adding the next. Rest days are part of getting better."}, "es": {"q": "¿Cómo organizo mi práctica siendo adulto?", "a": "Primero calienta unos minutos: camina, estírate con suavidad y rueda tranquilo. Varias sesiones cortas a la semana suelen funcionar bien. Para cuando todavía te sientas con energía, porque las piernas cansadas hacen más probables las caídas. Las protecciones de cadera o los shorts acolchados pueden suavizar las caídas de lado. Aprende una habilidad hasta que se sienta firme antes de pasar a la siguiente. Los días de descanso también son parte de mejorar."}}, {"id": "joining-sessions", "cat": "adults", "en": {"q": "How can I join a session or find other adult skaters?", "a": "Some cities have adult skate nights, lessons or meetups at local parks. Ask at a skate shop or check the park's notice board. At a session, say hello, watch for a bit and take turns. Nobody expects a beginner to be good, and most skaters remember starting out. You can practice in a quiet corner while others ride. Cheering for other people's tries is part of skate culture."}, "es": {"q": "¿Cómo me uno a una sesión o encuentro a otros adultos que patinan?", "a": "Algunas ciudades tienen noches de patineta para adultos, clases o reuniones en los parques. Pregunta en una tienda de patinetas o revisa el tablero de avisos del parque. En una sesión, saluda, observa un rato y toma turnos. Nadie espera que un principiante lo haga bien, y la mayoría de los patinadores recuerdan cuando empezaron. Puedes practicar en una esquina tranquila mientras otros patinan. Echarle porras a los intentos de los demás es parte de la cultura de la patineta."}}, {"id": "why-bend-knees", "cat": "science", "room": "balance", "en": {"q": "Why should I bend my knees?", "a": "Bent knees lower your center of mass, so you are harder to tip over. They also work like springs. When the board hits a bump or you land, your legs bend and slow your body over a longer time. Stopping over a longer time means a smaller force on your body. Straight, stiff legs send each bump straight into your joints. That is why skaters ride with soft, bent knees."}, "es": {"q": "¿Por qué debo doblar las rodillas?", "a": "Con las rodillas dobladas, tu centro de masa queda más bajo, así que es más difícil que te caigas. Las rodillas también funcionan como resortes. Cuando la patineta pega con un bache o cuando caes, tus piernas se doblan y frenan tu cuerpo en más tiempo. Frenar en más tiempo significa una fuerza más pequeña sobre tu cuerpo. Las piernas rectas y rígidas mandan cada golpe directo a tus articulaciones. Por eso se patina con las rodillas suaves y dobladas."}}, {"id": "why-lean-forward", "cat": "science", "room": "ramp", "trick": "dropin", "en": {"q": "Why do I lean forward when I drop in?", "a": "On a ramp, the board speeds up as it rolls down the slope. If your body stays back, the board rolls out from under you and you fall backward. Leaning forward keeps your center of mass over the board as it speeds up. Then your body and the board move together. Put weight on your front foot and press the front wheels down onto the ramp. Leaning in feels scary at first, but it is what keeps you up."}, "es": {"q": "¿Por qué me inclino hacia adelante en el drop in?", "a": "En una rampa, la patineta acelera mientras baja por la pendiente. Si tu cuerpo se queda atrás, la patineta se sale de debajo de ti y te caes hacia atrás. Inclinarte hacia adelante mantiene tu centro de masa sobre la patineta mientras acelera. Así tu cuerpo y la patineta se mueven juntos. Pon peso en el pie de adelante y empuja las ruedas de adelante contra la rampa. Inclinarte da miedo al principio, pero es lo que te mantiene arriba."}}, {"id": "skate-wax", "cat": "science", "room": "grind", "trick": "boardslide", "en": {"q": "What is skate wax for, and why does it help?", "a": "Skate wax is a hard wax rubbed thinly on the edge of a curb, ledge or box so trucks and boards slide. Sliding is slowed by kinetic friction: f = μN. Wax fills tiny bumps in the surface and lowers μ, the coefficient of friction. Less friction means you keep more speed. On level ground, slide distance is v²/(2μg), so halving μ doubles the distance. Use a thin layer, ask first at a park, and never wax stairs or walkways."}, "es": {"q": "¿Para qué sirve la cera de patineta y por qué ayuda?", "a": "La cera de patineta es una cera dura que se frota en capa delgada en la orilla de un bordillo, un borde o una caja para que los trucks y la tabla se deslicen. Lo que frena el deslizamiento es la fricción cinética: f = μN. La cera rellena bultitos de la superficie y baja μ, el coeficiente de fricción. Con menos fricción conservas más velocidad. En piso plano, la distancia de deslizamiento es v²/(2μg), así que si μ baja a la mitad, la distancia se duplica. Usa una capa delgada, pregunta primero en el parque y nunca encerices escaleras ni banquetas."}}, {"id": "bigger-wheels-cracks", "cat": "science", "room": "build", "en": {"q": "Why do bigger wheels roll over cracks more easily?", "a": "A bigger wheel meets a crack or pebble at a gentler angle. The edge of the bump pushes more upward on the wheel and less straight back against it. So the wheel climbs over instead of stopping. A small wheel hits the same bump more head-on, and the board can stop suddenly while you keep going. Softer wheels help too, because they squish around small bumps. That is why cruising boards often have big, soft wheels."}, "es": {"q": "¿Por qué las ruedas grandes pasan mejor por las grietas?", "a": "Una rueda grande choca con una grieta o una piedrita en un ángulo más suave. La orilla del bache empuja la rueda más hacia arriba y menos hacia atrás. Así la rueda se sube y pasa en vez de detenerse. Una rueda chica pega con el mismo bache más de frente, y la patineta se puede frenar de golpe mientras tú sigues hacia adelante. Las ruedas blandas también ayudan, porque se aplastan un poco alrededor de los bultitos. Por eso las patinetas para pasear suelen tener ruedas grandes y blandas."}}]
};
